/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> closestNodes(TreeNode* root, vector<int>& queries) {
        vector<vector<int>> res;
        for (int q : queries) {
            int pred = -1, succ = -1;
            TreeNode* node = root;
            while (node) {
                if (q == node->val) { pred = succ = q; break; }
                else if (q < node->val) { succ = node->val; node = node->left; }
                else { pred = node->val; node = node->right; }
            }
            res.push_back({pred, succ});
        }
        return res;
    }
};

