    public List<List<Integer>> closestNodes(TreeNode root, List<Integer> queries) {
        List<List<Integer>> res = new ArrayList<>();
        for (int q : queries) {
            int pred = -1, succ = -1;
            TreeNode node = root;
            while (node != null) {
                if (q == node.val) { pred = succ = q; break; }
                else if (q < node.val) { succ = node.val; node = node.left; }
                else { pred = node.val; node = node.right; }
            }
            res.add(Arrays.asList(pred, succ));
        }
        return res;
    }
}

