/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 * }
 */
class Solution {
    public List<List<Integer>> closestNodes(TreeNode root, List<Integer> queries) {
        List<Integer> vals = new ArrayList<>();
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode node = root;
        while (!st.isEmpty() || node != null) {
            while (node != null) { st.push(node); node = node.left; }
            node = st.pop();
            vals.add(node.val);
            node = node.right;
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int q : queries) {
            int i = Collections.binarySearch(vals, q);
            if (i < 0) i = -(i + 1); // insertion point = count of values <= q
            else i++;                 // exact match: bisect_right semantics
            int lo = i > 0 ? vals.get(i - 1) : -1;
            int hi = i < vals.size() ? vals.get(i) : -1;
            res.add(Arrays.asList(lo, hi));
        }
        return res;
    }
}

