var closestNodes = function(root, queries) {
    const vals = [];
    const st = [];
    let node = root;
    while (st.length || node) {
        while (node) { st.push(node); node = node.left; }
        node = st.pop();
        vals.push(node.val);
        node = node.right;
    }
    const res = [];
    for (const q of queries) {
        let lo = 0, hi = vals.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (vals[mid] <= q) lo = mid + 1; else hi = mid;
        }
        res.push([lo > 0 ? vals[lo - 1] : -1, lo < vals.length ? vals[lo] : -1]);
    }
    return res;
};
